# Update static contract from failed V6 to V7 geometry-only renderer API.
contract_old = '''    success &= check(has(renderer, "EXPERIMENTAL_INDEPENDENT_PARTIAL_PHASE_V6")\n                         && has(renderer, "if (frameSize_ == 256 && !nearestPeak_.empty())")\n                         && !has(renderer, "if (frameSize_ <= 256 && !nearestPeak_.empty())"),\n                     "experimental_128_keeps_independent_partial_phase_velocity");\n'''
contract_new = '''    success &= check(has(renderer, "EXPERIMENTAL_HARMONIC_COORDINATE_TRANSPORT_V7")\n                         && has(renderer, "transportTargetBin = measuredSourceBin + harmonicShiftBins")\n                         && has(renderer, "harmonicSourceBin * (safeRatio - 1.0)")\n                         && has(rendererHeader, "double sourceFundamentalHz = 0.0")\n                         && !has(rendererHeader, "confidence")\n                         && !has(rendererHeader, "voicing"),\n                     "experimental_128_uses_geometry_only_harmonic_coordinate_transport");\n'''
replace_once("Tests/GuiAudioControlContractTest.cpp", contract_old, contract_new)

